#!/bin/bash
##########################################################################################
# Submits CCWS test artifacts (generated by `test`/`ctest`/`wstest`/`wsctest` targets)
# to a CDash server without re-running tests.
#
# usage: ccws_cdash_submit.sh <artifacts_dir> <site> <build_name>
#
# parameters:
#   artifacts_dir -- per-package artifacts directory, e.g. artifacts/<profile>/<pkg>
#   site -- CDash site name, e.g. CI runner identifier or hostname
#   build_name -- CDash build name, usually includes profile, distro and package
#
# environment:
#   CDASH_URL (required) -- CDash base url, e.g. https://my.cdash.org
#   CDASH_PROJECT (required) -- project name on the server
#   CDASH_TOKEN -- authentication token, must come from env or CI secrets
#   CDASH_DRY_RUN -- if nonempty, print commands instead of executing them
#
# Everything is submitted through the classic XML channel understood by every
# CDash version including 5.x (file type is detected from the content):
#   PUT <url>/submit.php?project=<p>&FileName=<site>___<build>___<stamp>___XML___<Type>.xml&MD5=<md5>
# Test.xml gets site / build name / stamp recorded by ctest substituted
# ("(empty)" values in files generated outside of CDash dashboard mode);
# JUnit/xUnit files (gtest, ament) are wrapped into a CTest-style <Site> envelope
# which binds them to the same build, the multipart POST upload of CDash 2.x/3.x
# is rejected by current servers (POST requests are routed to a handler that
# requires a different parameter set);
# Coverage.xml / CoverageLog.xml are generated from gcovr lcov data by
# ccws_lcov2cdash.py and carry the same "(empty)" placeholders.
##########################################################################################

set -u

ARTIFACTS_DIR=${1:?CCWS: artifacts directory must be specified}
CDASH_SITE=${2:?CCWS: CDash site must be specified}
CDASH_BUILD=${3:?CCWS: CDash build name must be specified}

: ${CDASH_URL:?CCWS: CDASH_URL must be specified}
: ${CDASH_PROJECT:?CCWS: CDASH_PROJECT must be specified}
CDASH_TOKEN=${CDASH_TOKEN:-}
CDASH_DRY_RUN=${CDASH_DRY_RUN:-}

case "${CDASH_SITE}${CDASH_BUILD}" in
    *[\"\']*)
        echo "CCWS: site and build name must not contain quotes" >&2
        exit 1;;
esac

CURL=(curl --fail --silent --show-error --retry 3 --retry-delay 3)
if [ -n "${CDASH_TOKEN}" ]
then
    CURL+=(-H "Authorization: Bearer ${CDASH_TOKEN}")
fi

FAILED=0

# prints command with masked token in dry-run mode, executes it otherwise
run_or_print()
{
    if [ -n "${CDASH_DRY_RUN}" ]
    then
        printf '%q ' "${CURL[@]}" "$@"
        echo
    else
        if ! RESPONSE=$("${CURL[@]}" "$@" 2>&1)
        then
            echo "CCWS: submission failed: ${RESPONSE}" >&2
            FAILED=1
            return
        fi
        echo "${RESPONSE}" | grep -q '<status>OK</status>' > /dev/null 2>&1 \
            || echo "CCWS: warning: unexpected response: ${RESPONSE}" >&2
    fi
}

# stamp of the most recent test run, matches Testing/<stamp> selected below
STAMP=$(date -u '+%Y%m%d-%H%M')
if [ -f "${ARTIFACTS_DIR}/Testing/TAG" ]
then
    STAMP=$(head -n 1 "${ARTIFACTS_DIR}/Testing/TAG")
fi


##########################################################################################
# native CTest results

TEST_XML="${ARTIFACTS_DIR}/Testing/${STAMP}/Test.xml"
if [ -f "${TEST_XML}" ]
then
    # substitute site / build name / stamp recorded by ctest at test time
    # ("(empty)" values in files generated outside of CDash dashboard mode)
    PATCHED_XML=$(mktemp)
    sed \
        -e "0,/BuildName=\"[^\"]*\"/s//BuildName=\"${CDASH_BUILD//&/\\&}\"/" \
        -e "0,/BuildStamp=\"[^\"]*\"/s//BuildStamp=\"${STAMP}-Experimental\"/" \
        -e "0,/[[:space:]]Name=\"[^\"]*\"/s//	Name=\"${CDASH_SITE//&/\\&}\"/" \
        "${TEST_XML}" > "${PATCHED_XML}"
    MD5=$(md5sum "${PATCHED_XML}" | cut -f 1 -d ' ')
    run_or_print -X PUT -H "Content-Type: text/xml" \
        --data-binary "@${PATCHED_XML}" \
        "${CDASH_URL}/submit.php?project=${CDASH_PROJECT}&FileName=${CDASH_SITE}___${CDASH_BUILD}___${STAMP}-Experimental___XML___Test.xml&MD5=${MD5}"
    rm -f "${PATCHED_XML}"
else
    echo "CCWS: no Test.xml in ${ARTIFACTS_DIR}, skipping CTest results"
fi


##########################################################################################
# JUnit / xUnit results (gtest, ament, colcon)

JUNIT_COUNT=0
while IFS= read -r JUNIT_XML
do
    JUNIT_COUNT=$((JUNIT_COUNT + 1))
    WRAPPED_XML=$(mktemp)
    # the `timestamp` attribute has to be stripped: CDash ignores it when a Site
    # envelope is present and would otherwise set build times to epoch 0
    {
        echo '<?xml version="1.0" encoding="UTF-8"?>'
        echo "<Site BuildName=\"${CDASH_BUILD}\" BuildStamp=\"${STAMP}-Experimental\" Name=\"${CDASH_SITE}\" Generator=\"ccws-cdash-submit\">"
        sed -e '1{/^<?xml[[:space:]]/d}' \
            -e '/^[[:space:]]*<testsuite/s/[[:space:]]timestamp="[^"]*"//' \
            "${JUNIT_XML}"
        echo '</Site>'
    } > "${WRAPPED_XML}"
    MD5=$(md5sum "${WRAPPED_XML}" | cut -f 1 -d ' ')
    run_or_print -X PUT -H "Content-Type: text/xml" \
        --data-binary "@${WRAPPED_XML}" \
        "${CDASH_URL}/submit.php?project=${CDASH_PROJECT}&FileName=${CDASH_SITE}___${CDASH_BUILD}___${STAMP}-Experimental___XML___TestJUnit-$(basename "${JUNIT_XML}")&MD5=${MD5}"
    rm -f "${WRAPPED_XML}"
done < <(find "${ARTIFACTS_DIR}/test_results" -type f -name '*.xml' 2> /dev/null | sort)


##########################################################################################
# coverage results (generated by the `coverage` build profile, see
# bp_coverage_process_pkg and ccws_lcov2cdash.py)

COVERAGE_COUNT=0
for COVERAGE_XML in "${ARTIFACTS_DIR}"/Coverage*.xml
do
    [ -e "${COVERAGE_XML}" ] || continue
    COVERAGE_COUNT=$((COVERAGE_COUNT + 1))
    PATCHED_XML=$(mktemp)
    sed \
        -e "0,/BuildName=\"[^\"]*\"/s//BuildName=\"${CDASH_BUILD//&/\\&}\"/" \
        -e "0,/BuildStamp=\"[^\"]*\"/s//BuildStamp=\"${STAMP}-Experimental\"/" \
        -e "0,/[[:space:]]Name=\"[^\"]*\"/s//	Name=\"${CDASH_SITE//&/\\&}\"/" \
        "${COVERAGE_XML}" > "${PATCHED_XML}"
    MD5=$(md5sum "${PATCHED_XML}" | cut -f 1 -d ' ')
    run_or_print -X PUT -H "Content-Type: text/xml" \
        --data-binary "@${PATCHED_XML}" \
        "${CDASH_URL}/submit.php?project=${CDASH_PROJECT}&FileName=${CDASH_SITE}___${CDASH_BUILD}___${STAMP}-Experimental___XML___$(basename "${COVERAGE_XML}")&MD5=${MD5}"
    rm -f "${PATCHED_XML}"
done

echo "CCWS: ${ARTIFACTS_DIR}: submitted Test.xml, ${JUNIT_COUNT} junit and ${COVERAGE_COUNT} coverage files (stamp=${STAMP})"

exit ${FAILED}
